    h += '<div class="fmrow"><label><input type="checkbox" id="fgAuto"' + (G.autoOn ? ' checked' : '') + '> <b>Automatic</b> (satellite, terrain, watershed, retention and sensor sites once the field is drawn)</label></div><div class="fmrow"><button class="btn pri" id="fgRead">Read the terrain (contours, flow, watershed)</button><label>around the field <select id="fgBuf">' + [150, 250, 400, 700, 1000].map(v => '<option' + (v === G.buf ? ' selected' : '') + '>' + v + '</option>').join('') + '</select> m</label></div><div id="fgSt" class="pnote">' + (T ? 'Terrain read: ' + (T.D.W * T.D.H).toLocaleString('en-US') + ' cells of ' + T.cell.toFixed(1) + ' m, ' + esc(T.src) + '.' + (G.msg ? '<br>' + G.msg : '') : 'Reads the elevation around the field, then draws contours, flow lines, the wetness index and the watershed.') + '</div>';
