    h += '<h4 style="margin:10px 0 4px">Soil retention curves, mapped (geostatistics)</h4><div class="pnote">Soil samples (one per line: latitude, longitude, sand %, clay %, organic matter % optional). Without samples the SoilGrids value of the field is varied with the wetness index (an indicative trend, set below); with samples the maps are kriged, and the trend on the wetness index and the satellite index is fitted to them when there are enough samples.</div><div class="fmrow"><label title="Without samples, vary the soil with the wetness index of the terrain"><input type="checkbox" id="fgTr"' + (G.trend ? ' checked' : '') + '> indicative terrain trend: clay <input id="fgBC" type="number" step="0.5" value="' + G.bC + '" style="width:54px"> sand <input id="fgBS" type="number" step="0.5" value="' + G.bS + '" style="width:54px"> points per SD of wetness index</label></div><textarea id="fgSmp" rows="3" style="width:100%" placeholder="9.0831, 7.4012, 62, 18">' + esc(G.samples) + '</textarea><div class="fmrow"><button class="btn pri" id="fgRet"' + (T ? '' : ' disabled') + '>Map the retention curves</button><button class="btn" id="fgDSS"' + (R ? '' : ' disabled') + ' title="Set the soil of the program to the class of the field mean and the field area">Use this field in the DSS</button></div><div id="fgRSt" class="pnote" aria-live="polite">' + (G.rmsg ? rlogH() + G.rmsg : (R ? 'Retention mapped: ' + esc(R.how) + '.' : 'Not read yet: it reads the soil of the field (SoilGrids), the wetness of the terrain and the satellite, and your soil samples if you typed any.')) + '</div>';
    if (R) { const a = stat(R.AW), fcS = stat(R.FC), wpS = stat(R.WP), dS = stat(R.DAYS); h += '<div class="fmzt"><b>Retention of the field</b> <small>(' + esc(R.how) + ')</small><table class="tbl fmtab"><tr><th></th><th>mean</th><th>10 %</th><th>90 %</th></tr><tr><td>Field capacity</td><td>' + (fcS.m * 100).toFixed(1) + ' %</td><td>' + (fcS.p10 * 100).toFixed(1) + '</td><td>' + (fcS.p90 * 100).toFixed(1) + '</td></tr><tr><td>Wilting point</td><td>' + (wpS.m * 100).toFixed(1) + ' %</td><td>' + (wpS.p10 * 100).toFixed(1) + '</td><td>' + (wpS.p90 * 100).toFixed(1) + '</td></tr><tr><td>Available water</td><td><b>' + (a.m * 100).toFixed(1) + ' %</b></td><td>' + (a.p10 * 100).toFixed(1) + '</td><td>' + (a.p90 * 100).toFixed(1) + '</td></tr><tr><td>Days to the trigger (f = ' + R.f.toFixed(2) + ', roots ' + Math.round(R.zr) + ' cm, ETc ' + R.etc.toFixed(1) + ' mm/day)</td><td>' + dS.m.toFixed(1) + '</td><td>' + (dS.p10).toFixed(1) + '</td><td>' + (dS.p90).toFixed(1) + '</td></tr></table>' +
      '<div class="pnote">The field irrigates when its driest cells reach the trigger: first cell in ' + (dS.p10 != null ? dS.p10.toFixed(1) : '-') + ' days against ' + dS.m.toFixed(1) + ' on average' + (b && b.next ? '; the DSS (one soil for the whole field) gives ' + esc(b.next) : '') + '.</div><div class="fmrow"><button class="btn" data-v="ret_fc">Field capacity</button><button class="btn" data-v="ret_wp">Wilting point</button><button class="btn" data-v="ret_aw">Available water</button><button class="btn" data-v="ret_trig">Trigger</button><button class="btn" data-v="ret_psi">Matric potential now</button><button class="btn" data-v="ret_days">Days to the trigger</button></div><canvas id="fgRC" width="540" height="250" style="max-width:100%"></canvas><canvas id="fgV1" width="540" height="150" style="max-width:100%"></canvas></div>'; }
